// listRegistryTags is the seam the tag search reads a registry through; tests
// swap it.
var listRegistryTags = oci.ListRegistryTagsContext

// nextBrowserGen returns a fresh generation. Called from Update only (Rule 110).
func nextBrowserGen() uint64 { return browserGen.Add(1) }

// beginRequests cancels the lot in flight and opens a new one: a new
// generation, a fresh context, no pending search. Call it only once a request
// is certain to start, so a refused validation leaves the running lot alone.
func (b *RegistryBrowser) beginRequests() context.Context {
	b.cancelInFlight()
	ctx, cancel := context.WithCancel(context.Background())
	b.cancel = cancel
	b.gen = nextBrowserGen()
	b.pendingSearches = 0
	return ctx
}

// abandonLot cancels the lot in flight and moves to a fresh generation with no
// pending search, so every late answer of that lot is dropped. Called from
// Update only (Rule 110).
func (b *RegistryBrowser) abandonLot() {
	b.cancelInFlight()
	b.gen = nextBrowserGen()
	b.pendingSearches = 0
}

// cancelInFlight cancels the lot's context, if any. Nil-safe.
func (b *RegistryBrowser) cancelInFlight() {
	if b == nil || b.cancel == nil {
		return
	}
	b.cancel()
	b.cancel = nil
}

// RegistryBrowserGen returns the generation the open browser accepts, 0 when it
// is closed. For tests, like ActivityTables.
func (m Model) RegistryBrowserGen() uint64 {
	if m.registryBrowser == nil {
	prev, hadSel := b.searchTable.Selected()
	b.searchTable.SetItems(rows)
	if !hadSel {
		b.searchTable.GotoTop()
	} else {
		for i, r := range b.searchTable.Visible() {
			if r.img.EntryKey == prev.img.EntryKey && r.img.Repo == prev.img.Repo {
				b.searchTable.SetCursor(i)
				break
			}
		}
	}
	b.resizeTables()
}

// AddImageResults takes one registry's answer. It returns false, touching
// nothing, when the answer belongs to another lot. pendingSearches never goes
// below zero.
func (b *RegistryBrowser) AddImageResults(msg ImageSearchResultMsg) bool {
	if msg.Gen != b.gen {
		return false
	}
	if b.pendingSearches > 0 {
		b.pendingSearches--
	}
	oc := imagesearch.Classify(msg.Err, len(msg.Images), msg.Partial)
	if b.outcomes == nil {
		b.outcomes = map[string]imagesearch.Outcome{}
	}
	b.outcomes[msg.EntryKey] = oc
	if oc.Verdict == imagesearch.VerdictOK {
		for _, img := range msg.Images {
			img.EntryKey = msg.EntryKey
			b.images = append(b.images, img)
		}
	}
	b.rebuildSearchTable()
	return true
}

// handleImagesKeyMsg handles the keys of the level 1 table. left goes straight
// back to the form; esc acts in order: the filter bar while it is open, then a
// confirmed query, then it cancels the lot and goes back to the form (which
// keeps the typed name and the selection). The lot's late answers are no
// longer wanted and are dropped
// (TestEscAtLevelOneCancelsTheLotAndIgnoresItsLateAnswers). enter does
// nothing: a row has no action yet; → opens the row's tags.
func (b *RegistryBrowser) handleImagesKeyMsg(msg tea.KeyPressMsg) (*RegistryBrowser, tea.Cmd) {
	if b.searchTable.InEditMode() {
		return b, b.searchTable.Update(msg)
	}
	switch msg.String() {
	case "right":
		return b.openSelectedImageTags()
	case "esc":
		if bar := b.searchTable.FilterBar(); bar.SearchQuery() != "" {
			bar.ClearSearch()
			b.searchTable.SetItems(b.searchTable.Items())
			return b, nil
		}
		return b.backToForm()
	case "left":
		return b.backToForm()
	case "enter":
		return b, nil
	}
	return b, b.searchTable.Update(msg)
}

// backToForm cancels the lot and returns to the form, which keeps the typed
// name and the selection. Late answers of the lot are dropped.
func (b *RegistryBrowser) backToForm() (*RegistryBrowser, tea.Cmd) {
	b.abandonLot()
	b.state = browserStateInput
	b.searchTable.Blur()
	b.updateFocus()
	return b, nil
}

// handleImageSearchResult records one registry's answer; a stale one is ignored.
func (m Model) handleImageSearchResult(msg ImageSearchResultMsg) (tea.Model, tea.Cmd) {
		normalizedRepo := joinRepoPrefix(entry.repoPrefix, normalizeRepoForRegistry(entry.URL, repo))
		reqs = append(reqs, b.newTagRequest(entry, normalizedRepo))
	}
	return b.startTagRequests(reqs, false)
}

// startTagRequests opens a lot, resets the tag table (tags, registry filter,
// text filter, default sort), records whether the lot comes from level 1, and
// sends one searchRegistryTagsCmd per request.
func (b *RegistryBrowser) startTagRequests(reqs []tagRequest, fromSearch bool) (*RegistryBrowser, tea.Cmd) {
	ctx := b.beginRequests()
	b.tagsFromSearch = fromSearch
	b.tagsImage = ""
	b.tags = nil
	b.registryFilter = resultFilter{}
	b.filterInput.SetValue("")
	b.filterActive = false
	// A new search starts from the default order, not wherever the last one's
	// `.` presses left the table.
	b.tagTable.SetSort(tagColumnTag, false)

	cmds := make([]tea.Cmd, 0, len(reqs))
	for _, r := range reqs {
		b.pendingSearches++
		cmds = append(cmds, searchRegistryTagsCmd(ctx, b.gen, r.entry.key, r.entry.URL, r.alias, r.apiURL, r.repo, r.user, r.pass))
	}

	b.state = browserStateTags
	b.searchTable.Blur()
	b.tagTable.Focus()
	b.rebuildTagTable()
	return b, tea.Batch(cmds...)
}

// leaveTags leaves the tag table: it abandons the tag lot, clears the tag
// filters and goes back where the table was opened from, level 1 untouched
// (same rows, order, cursor and filter, no new search) when right opened it,
// the search form otherwise. It returns no Cmd.
func (b *RegistryBrowser) leaveTags() (*RegistryBrowser, tea.Cmd) {
	b.abandonLot()
	b.tagsImage = ""
	b.registryFilter = resultFilter{}
	b.filterInput.SetValue("")
	b.filterActive = false
	b.tagTable.Blur()
